import { chromium } from 'playwright'
import fs from 'node:fs'

const BASE = 'http://localhost:5199'
const OUT = '/tmp/w5-verify/shots'
fs.mkdirSync(OUT, { recursive: true })
const parks = JSON.parse(fs.readFileSync('/Users/nicknavarro/Learn/find-parks-poc/src/data/parks.json', 'utf8'))

const browser = await chromium.launch({ channel: 'chrome' })
const report = []
const log = (...a) => { const s = a.join(' '); report.push(s); console.log(s) }

async function newPage(width, height) {
  const ctx = await browser.newContext({ viewport: { width, height } })
  const page = await ctx.newPage()
  const errors = []
  page.on('pageerror', (e) => errors.push('pageerror: ' + e.message))
  page.on('console', (m) => { if (m.type() === 'error') errors.push('console: ' + m.text()) })
  return { ctx, page, errors }
}

async function focusInfo(page) {
  return page.evaluate(() => {
    const el = document.activeElement
    if (!el || el === document.body) return { desc: 'body' }
    const cs = getComputedStyle(el)
    const text = (el.getAttribute('aria-label') || el.textContent || '').trim().replace(/\s+/g, ' ').slice(0, 50)
    return { desc: `${el.tagName.toLowerCase()} "${text}"`, ring: cs.boxShadow !== 'none' && cs.boxShadow.includes('rgb'), shadow: cs.boxShadow.slice(0, 80) }
  })
}

async function overflow(page) {
  return page.evaluate(() => document.documentElement.scrollWidth > document.documentElement.clientWidth)
}

for (const [width, height, label] of [[375, 812, 'mobile'], [1280, 800, 'desktop']]) {
  log(`\n=== ${label} ${width}px ===`)
  const { ctx, page, errors } = await newPage(width, height)

  // Home
  await page.goto(BASE + '/')
  await page.waitForTimeout(1500)
  const listCount = await page.locator('nav a[href^="/park/"]').count()
  log(`home: list links=${listCount}, h-overflow=${await overflow(page)}, searchbox name ok=${await page.getByRole('searchbox', { name: 'Search parks' }).count()}`)
  await page.screenshot({ path: `${OUT}/${label}-home.png` })

  if (label === 'mobile') {
    await page.getByRole('button', { name: 'Open map' }).click()
    await page.waitForTimeout(1500)
    log(`mobile map: markers=${await page.locator('.park-marker').count()}, focused=${(await focusInfo(page)).desc}, attribution=${await page.locator('.leaflet-control-attribution').innerText().catch(() => 'none')}`)
    await page.screenshot({ path: `${OUT}/mobile-map.png` })
    await page.getByRole('button', { name: 'Show list' }).click()
    await page.waitForTimeout(300)
  } else {
    log(`desktop: markers=${await page.locator('.park-marker').count()}, attribution=${await page.locator('.leaflet-control-attribution').innerText().catch(() => 'none')}`)
  }

  // Search
  for (const q of ['dog', 'trails', 'WiFi', 'zzz']) {
    await page.goto(BASE + '/')
    await page.waitForTimeout(800)
    await page.getByRole('searchbox').fill(q)
    await page.waitForTimeout(600)
    const items = await page.locator('nav a[href^="/park/"]').count()
    const h1 = (await page.locator('h1').first().innerText()).replace(/\s+/g, ' ')
    let markers
    if (label === 'mobile') {
      await page.getByRole('button', { name: 'Open map' }).click()
      await page.waitForTimeout(1000)
      markers = await page.locator('.park-marker').count()
      if (q === 'dog') await page.screenshot({ path: `${OUT}/mobile-map-search-dog.png` })
      await page.getByRole('button', { name: 'Show list' }).click()
      await page.waitForTimeout(300)
    } else {
      markers = await page.locator('.park-marker').count()
      if (q === 'dog') await page.screenshot({ path: `${OUT}/desktop-search-dog.png` })
    }
    const empty = await page.getByText('No parks match').count()
    log(`search "${q}": url=${page.url().replace(BASE, '')}, list=${items}, markers=${markers}, h1="${h1}", emptyState=${empty}`)
  }

  // Keyboard: list -> detail -> back
  await page.goto(BASE + '/')
  await page.waitForTimeout(1000)
  const stops = []
  let reachedItem = false
  for (let i = 0; i < 8; i++) {
    await page.keyboard.press('Tab')
    const f = await focusInfo(page)
    stops.push(`${f.desc}${f.ring ? ' [ring]' : ' [NO RING]'}`)
    const isItem = await page.evaluate(() => document.activeElement?.closest('nav') && document.activeElement?.getAttribute('href')?.startsWith('/park/'))
    if (isItem) { reachedItem = true; break }
  }
  log(`tab stops: ${stops.join(' -> ')}`)
  await page.screenshot({ path: `${OUT}/${label}-focus-list.png` })
  if (reachedItem) {
    await page.keyboard.press('Enter')
    await page.waitForTimeout(800)
    log(`after Enter: url=${page.url().replace(BASE, '')}`)
    await page.keyboard.press('Tab')
    const f = await focusInfo(page)
    log(`detail first tab: ${f.desc} ring=${f.ring}`)
    await page.screenshot({ path: `${OUT}/${label}-focus-back.png` })
    await page.keyboard.press('Enter')
    await page.waitForTimeout(800)
    log(`after Enter on back: url=${page.url().replace(BASE, '')}`)
  }

  // Keyboard with search preserved
  await page.goto(BASE + '/?q=dog')
  await page.waitForTimeout(800)
  for (let i = 0; i < 6; i++) {
    await page.keyboard.press('Tab')
    const isItem = await page.evaluate(() => document.activeElement?.getAttribute('href')?.startsWith('/park/'))
    if (isItem) break
  }
  await page.keyboard.press('Enter'); await page.waitForTimeout(600)
  await page.keyboard.press('Tab'); await page.keyboard.press('Enter'); await page.waitForTimeout(600)
  log(`search round trip via keyboard: url=${page.url().replace(BASE, '')}, input=${await page.getByRole('searchbox').inputValue()}`)

  // Desktop: tab from last list item into markers
  if (label === 'desktop') {
    await page.goto(BASE + '/')
    await page.waitForTimeout(1200)
    await page.locator('nav a[href^="/park/"]').last().focus()
    await page.keyboard.press('Tab')
    await page.waitForTimeout(600)
    const f = await focusInfo(page)
    const outline = await page.evaluate(() => getComputedStyle(document.activeElement).boxShadow)
    log(`tab after last list item: ${f.desc} ring=${f.ring} popupOpen=${await page.locator('.leaflet-popup').count()}`)
    await page.screenshot({ path: `${OUT}/desktop-focus-marker.png` })
    await page.keyboard.press('Tab')
    log(`tab from marker: ${(await focusInfo(page)).desc}`)
    await page.keyboard.press('Enter'); await page.waitForTimeout(600)
    log(`enter on popup link: url=${page.url().replace(BASE, '')}`)
    void outline
    // Mouse click on marker opens popup once
    await page.goto(BASE + '/'); await page.waitForTimeout(1200)
    await page.locator('.park-marker').first().click(); await page.waitForTimeout(500)
    log(`mouse click marker: popups=${await page.locator('.leaflet-popup').count()}`)
  }

  // Every detail page
  for (const p of parks) {
    await page.goto(`${BASE}/park/${p.id}`)
    await page.waitForTimeout(400)
    const data = await page.evaluate(() => {
      const main = document.querySelector('main')
      return {
        h1: document.querySelector('h1')?.textContent,
        text: main?.innerText ?? '',
        rows: Array.from(document.querySelectorAll('section[aria-labelledby="park-details-heading"] dt, section[aria-labelledby="park-details-heading"] div > div')).map((e) => e.textContent).slice(0, 8),
        stars: document.querySelector('[role="img"][aria-label^="Rated"]')?.getAttribute('aria-label') ?? null,
        imgs: document.querySelectorAll('main img').length,
        placeholders: document.querySelectorAll('[aria-label="No photo available"]').length,
        title: document.title,
      }
    })
    const problems = []
    if (data.h1 !== p.name) problems.push(`h1 ${data.h1}`)
    const addr = p.location?.address ?? null
    if (addr && !data.text.includes(addr)) problems.push('address missing')
    if (!addr && /Address/.test(data.text)) problems.push('address row shown without address')
    if (p.description ? !data.text.includes(p.description) : !data.text.includes('No description available')) problems.push('description')
    if (!data.text.includes(p.hours)) problems.push('hours')
    if (!data.text.includes(`${p.acreage} acre`)) problems.push('acreage')
    if (p.rating === null ? !data.text.includes('No rating yet') || data.stars : !data.text.includes(`${p.rating.toFixed(1)} / 5`) || data.stars !== `Rated ${p.rating.toFixed(1)} out of 5`) problems.push(`rating stars=${data.stars}`)
    if (p.images.length === 0 && /Photos/.test(data.text)) problems.push('photos heading with no images')
    if (overflowAny) {}
    const ov = await overflow(page)
    if (ov) problems.push('horizontal overflow')
    log(`detail ${p.id}: imgs=${data.imgs} placeholders=${data.placeholders} stars=${data.stars} title="${data.title}" ${problems.length ? 'PROBLEMS: ' + problems.join('; ') : 'OK'}`)
    if (['highland-dog-park', 'prospect-park', 'old-mill-botanical-garden', 'cedar-hill-nature-preserve'].includes(p.id)) {
      await page.screenshot({ path: `${OUT}/${label}-detail-${p.id}.png`, fullPage: true })
    }
  }

  await page.goto(`${BASE}/park/does-not-exist`)
  await page.waitForTimeout(300)
  log(`unknown id: h1="${await page.locator('h1').innerText()}", home link=${await page.getByRole('link', { name: 'Back to all parks' }).getAttribute('href')}`)

  log(`errors (${label}): ${errors.length ? errors.join(' | ') : 'none'}`)
  await ctx.close()
}

var overflowAny
await browser.close()
fs.writeFileSync('/tmp/w5-verify/report.txt', report.join('\n'))

