  console.log(`desktop q="${q}": markers=${xs.length} hiddenUnderPanel=${xs.filter((x) => x <= panelRight + 4).length} panelRight=${panelRight} xs=${xs.join(',')}`)
}

const m = await (await browser.newContext({ viewport: { width: 375, height: 812 } })).newPage()
await m.goto(BASE + '/')
await m.waitForTimeout(1500)
for (let i = 0; i < 3; i++) {
  await m.keyboard.press('Tab')
  console.log('mobile tab', i, await m.evaluate(() => document.activeElement?.outerHTML.slice(0, 120)))
}
await browser.close()

